export const generateAnalyticalQuestions = async (profile: ApplicantProfile): Promise<AnalyticalQuestion[]> => {
  const prompt = `قم بإنشاء 5 أسئلة تحليلية لمجال ${profile.sector}. الرد JSON فقط.`;
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: { responseMimeType: "application/json" }
    });
    return JSON.parse(response.text || "[]");
  } catch (e) { return []; }
};

export const evaluateProjectIdea = async (ideaText: string, profile: ApplicantProfile): Promise<ProjectEvaluationResult> => {
  const prompt = `قيم فكرة المشروع: ${ideaText} في مجال ${profile.sector}. الرد JSON.`;
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: { responseMimeType: "application/json" }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return { clarity: 10, value: 10, innovation: 10, market: 10, readiness: 10, totalScore: 50, aiOpinion: "Error", classification: "Yellow" };
  }
};

