export const runProjectAgents = async (name: string, desc: string, agents: string[]): Promise<any> => {
  const prompt = `
    أنت مجموعة من وكلاء الذكاء الاصطناعي تعمل لبناء مشروع: "${name}".
    وصف المشروع: "${desc}"
    الوكلاء المفعلون: ${agents.join(', ')}

    المطلوب توليد:
    1. رؤية استراتيجية (Vision).
    2. تحليل للسوق والمنافسين.
    3. شخصيات مستخدمين (User Personas).
    4. قائمة بـ 5 فرضيات عمل أساسية (Hypotheses).

    الرد يجب أن يكون بصيغة JSON صارمة.
  `;

  try {
    const response = await ai.models.generateContent({
      model: PRO_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            vision: { type: Type.STRING },
            market: { type: Type.STRING },
            users: { type: Type.STRING },
            hypotheses: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { vision: "رؤية افتراضية", market: "تحليل افتراضي", users: "مستخدمين افتراضيين", hypotheses: ["فرضية 1"] };
  }
};

export const generatePitchDeck = async (name: string, desc: string, data: any): Promise<PitchSlide[]> => {
  const prompt = `
    بناءً على بيانات المشروع التالية:
    الاسم: ${name}
    البيانات: ${JSON.stringify(data)}

    أنشئ عرضاً تقديمياً (Pitch Deck) مكوناً من 6 شرائح:
    1. العنوان والمشكلة.
    2. الحل.
    3. حجم السوق.
    4. نموذج العمل.
    5. الفريق والرؤية.
    6. الخاتمة.

    الرد JSON Array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: PRO_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING },
              visualHint: { type: Type.STRING }
            }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return [{ title: "شريحة افتراضية", content: "محتوى افتراضي", visualHint: "صورة توضيحية" }];
  }
};

