export const analyzeExportOpportunity = async (data: any): Promise<any> => {
  const prompt = `
    أنت محرك NEDE المتخصص في تحليل فرص التصدير العالمية.
    بناءً على البيانات التالية:
    المنتج: ${data.productType}
    القطاع: ${data.sector}
    جاهزية الإنتاج: ${data.readiness}
    السوق المستهدف: ${data.targetMarket}
    التوقيت: ${data.timing}

    قم بتحليل:
    1. الطلب العالمي (Global Demand).
    2. المتطلبات التنظيمية (Regulatory Requirements).
    3. المخاطر اللوجستية (Logistic Risks).
    4. التوقيت والموسمية (Timing/Seasonality).

    ثم اتخذ قراراً: (EXPORT_NOW, WAIT, DONT_EXPORT).
    وأخيراً قدم توصيات لأسواق بديلة.

    الرد JSON فقط.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            analysis: {
              type: Type.OBJECT,
              properties: {
                demand: { type: Type.STRING },
                regulations: { type: Type.STRING },
                risks: { type: Type.STRING },
                seasonality: { type: Type.STRING }
              }
            },
            decision: { type: Type.STRING, description: "One of: EXPORT_NOW, WAIT, DONT_EXPORT" },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { 
      analysis: { demand: "طلب مستقر", regulations: "إجراءات قياسية", risks: "مخاطر منخفضة", seasonality: "توقيت مناسب" },
      decision: "EXPORT_NOW",
      recommendations: ["سوق الخليج العربي", "شمال أفريقيا"]
    };
  }
};

