import { GoogleGenAI, Type } from "@google/genai";
import { FailureSimulation, GovStats } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

export const simulateBrutalTruth = async (data: any): Promise<FailureSimulation> => {
  const prompt = `
    أنت محرك "الحقيقة القاسية" للتصدير. لا تجامل، كن واقعياً جداً وربما قاسياً في نقد فرصة التصدير التالية:
    المنتج: ${data.productType}
    السوق: ${data.targetMarket}
    الجاهزية: ${data.readiness}

    المطلوب:
    1. احتمالية الفشل (نسبة مئوية).
    2. الخسارة المالية المتوقعة (تقدير).
    3. التأثير التشغيلي.
    4. "محرك الأسئلة المفقودة": 3 أسئلة جوهرية لم يفكر فيها المصدّر.
    5. خطة التعافي الذكي (3 خطوات).
    6. الحقيقة القاسية (جملة واحدة صادمة).

    الرد JSON فقط.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            probability: { type: Type.NUMBER },
            financialLoss: { type: Type.STRING },
            operationalImpact: { type: Type.STRING },
            missingQuestions: { type: Type.ARRAY, items: { type: Type.STRING } },
            recoveryPlan: { type: Type.ARRAY, items: { type: Type.STRING } },
            brutalTruth: { type: Type.STRING }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    throw e;
  }
};

export const getGovInsights = async (): Promise<GovStats> => {
  const prompt = `قم بتوليد بيانات إحصائية وهمية ولكن واقعية لتقرير تصدير وطني. الرد JSON فقط.`;
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            riskyMarkets: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { name: { type: Type.STRING }, failRate: { type: Type.NUMBER } } } },
            readySectors: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { name: { type: Type.STRING }, score: { type: Type.NUMBER } } } },
            commonFailReasons: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { reason: { type: Type.STRING }, percentage: { type: Type.NUMBER } } } },
            regulatoryGaps: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    return JSON.parse(response.text);
  } catch (e) {
    return { riskyMarkets: [], readySectors: [], commonFailReasons: [], regulatoryGaps: [] };
  }
};

