export const evaluateProjectIdea = async (description: string, profile: ApplicantProfile): Promise<ProjectEvaluationResult> => {
  const prompt = `
    أنت مستشار ريادي خبير في مسرعة أعمال. قم بتقييم فكرة المشروع التالية لمتقدم يعمل في قطاع ${profile.sector} وفي مرحلة ${profile.projectStage}:

    الفكرة/المشروع: "${description}"

    قم بتحليل الفكرة عبر 5 محاور، مع إعطاء درجة من 20 لكل محور:
    1. وضوح الفكرة (Clarity): مدى وضوح المشكلة والحل.
    2. القيمة المقترحة (Value): الفائدة الحقيقية للعملاء.
    3. التميز والابتكار (Innovation): الإبداع والميزة التنافسية.
    4. الجدوى السوقية (Market): حجم السوق والحاجة إليه.
    5. الجاهزية للتنفيذ (Readiness): إمكانية التطبيق الفوري.

    المجموع الكلي يجب أن يكون من 100.

    التصنيف (classification):
    - Green: إذا كان المجموع 80-100 (جاهز للاحتضان).
    - Yellow: إذا كان المجموع 60-79 (يحتاج تطوير).
    - Red: إذا كان المجموع أقل من 60 (غير واضح/مرفوض).

    المطلوب رد JSON فقط بالهيكل التالي:
    {
      "clarity": number,
      "value": number,
      "innovation": number,
      "market": number,
      "readiness": number,
      "totalScore": number,
      "aiOpinion": "نص باللغة العربية يشرح الرأي الموضوعي",
      "classification": "Green" | "Yellow" | "Red"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clarity: { type: Type.NUMBER },
            value: { type: Type.NUMBER },
            innovation: { type: Type.NUMBER },
            market: { type: Type.NUMBER },
            readiness: { type: Type.NUMBER },
            totalScore: { type: Type.NUMBER },
            aiOpinion: { type: Type.STRING },
            classification: { type: Type.STRING, enum: ['Green', 'Yellow', 'Red'] }
          },
          required: ["clarity", "value", "innovation", "market", "readiness", "totalScore", "aiOpinion", "classification"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    console.error("AI Evaluation Error:", e);
    // Return a safe fallback
    return {
      clarity: 10, value: 10, innovation: 10, market: 10, readiness: 10,
      totalScore: 50, aiOpinion: "عذراً، تعذر التحليل حالياً. يرجى المحاولة لاحقاً.",
      classification: 'Yellow'
    };
  }
};

