import React, { useState } from 'react';
import { ApplicantProfile, ProjectEvaluationResult } from '../../types';
import { evaluateProjectIdea } from '../../services/geminiService';
import { playCelebrationSound, playPositiveSound, playErrorSound } from '../../services/audioService';

interface ProjectEvaluationProps {
  profile: ApplicantProfile;
  onComplete: (result: ProjectEvaluationResult) => void;
}

export const ProjectEvaluation: React.FC<ProjectEvaluationProps> = ({ profile, onComplete }) => {
  const [ideaText, setIdeaText] = useState('');
  const [inputMode, setInputMode] = useState<'text' | 'file'>('text');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<ProjectEvaluationResult | null>(null);

  const handleAnalyze = async () => {
    if (!ideaText.trim() && inputMode === 'text') return;

    setIsAnalyzing(true);
    playPositiveSound();

    try {
      // Simulate file content if file mode (mock logic for the demo)
      const textToAnalyze = inputMode === 'file' 
        ? `مشروع في مجال ${profile.sector} بمرحلة ${profile.projectStage}. تم رفع ملف توضيحي يتناول الحل المبتكر للمشكلة السوقية المحددة.` 
        : ideaText;

      const evalResult = await evaluateProjectIdea(textToAnalyze, profile);
      setResult(evalResult);

      if (evalResult.classification === 'Green') {
        playCelebrationSound();
      } else {
        playPositiveSound();
      }
    } catch (error) {
      console.error("Evaluation failed", error);
      playErrorSound();
    } finally {
      setIsAnalyzing(false);
    }
  };

  const getScoreColor = (score: number) => {
    if (score >= 16) return 'bg-green-500';
    if (score >= 12) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  const getClassColor = (cls: string) => {
    switch (cls) {
      case 'Green': return 'bg-green-100 text-green-800 border-green-200';
      case 'Yellow': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'Red': return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-gray-100';
    }
  };

  if (result) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="max-w-2xl w-full bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden animate-fade-in-up">

          {/* Header */}
          <div className="bg-slate-900 p-8 text-white flex justify-between items-center relative">
            <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600 rounded-bl-full opacity-10"></div>
            <div className="relative z-10">
              <h2 className="text-2xl font-bold">تقرير تحليل المشروع</h2>
              <p className="text-slate-400 text-sm">بيزنس ديفلوبرز • AI Analysis System</p>
            </div>
            <div className={`relative z-10 w-20 h-20 rounded-full flex flex-col items-center justify-center border-4 shadow-lg ${
                result.classification === 'Green' ? 'bg-green-600 border-green-400' : 
                result.classification === 'Yellow' ? 'bg-yellow-500 border-yellow-300' : 'bg-red-600 border-red-400'
              }`}>
              <span className="text-2xl font-black">{result.totalScore}</span>
              <span className="text-[10px] uppercase font-bold opacity-80">نقطة</span>
            </div>
          </div>

          <div className="p-8">
            <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
              <span className="w-2 h-8 bg-blue-600 rounded-full"></span>
              تحليل المحاور الخمسة
            </h3>

            {/* Axis Scores */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4 mb-8">
              {[
                { label: 'وضوح الفكرة', score: result.clarity, key: 'Clarity' },
                { label: 'القيمة المقترحة', score: result.value, key: 'Value' },
                { label: 'التميز والابتكار', score: result.innovation, key: 'Innovation' },
                { label: 'الجدوى السوقية', score: result.market, key: 'Market' },
                { label: 'الجاهزية للتنفيذ', score: result.readiness, key: 'Readiness' },
              ].map((item, idx) => (
                <div key={idx} className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                  <div className="flex justify-between text-xs font-bold text-slate-500 mb-2 uppercase tracking-tight">
                    <span>{item.label}</span>
