                demand: { type: Type.STRING },
                regulations: { type: Type.STRING },
                risks: { type: Type.STRING },
                seasonality: { type: Type.STRING }
              },
              required: ["demand", "regulations", "risks", "seasonality"]
            },
            recommendations: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["decision", "analysis", "recommendations"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    console.error("Export Analysis Error:", e);
    // Return safe fallback values matching the expected component structure
    return {
      decision: 'WAIT',
      analysis: {
        demand: 'تعذر التحليل حالياً. يرجى مراجعة السوق بشكل يدوي.',
        regulations: 'المتطلبات التنظيمية غير واضحة في الوقت الحالي.',
        risks: 'هناك مخاطر محتملة تتطلب مراجعة دقيقة.',
        seasonality: 'التوقيت الحالي قد يكون غير مناسب.'
      },
      recommendations: ['يرجى المحاولة مرة أخرى لاحقاً']
    };
  }
};

import React, { useState } from 'react';
