import React, { useState } from 'react';
import { FiltrationStage, ApplicantProfile, FinalResult, Badge, UserProfile, LevelData, LEVELS_CONFIG, ProjectEvaluationResult } from './types';
import { WelcomeStep } from './components/Filtration/WelcomeStep';
import { PersonalityTest } from './components/Filtration/PersonalityTest';
import { AnalyticalTest } from './components/Filtration/AnalyticalTest';
import { ProjectEvaluation } from './components/Filtration/ProjectEvaluation';
import { AssessmentResult } from './components/Filtration/AssessmentResult';
import { FinalReport } from './components/Filtration/FinalReport';
import { DevelopmentPlan } from './components/Filtration/DevelopmentPlan';
import { LandingPage } from './components/LandingPage';
import { PathFinder } from './components/PathFinder';
import { Dashboard } from './components/Dashboard';
import { LevelView } from './components/LevelView';
import { Certificate } from './components/Certificate';
import { ProjectBuilderMain } from './components/ProjectBuilder/ProjectBuilderMain';
import { SmartFeatures } from './components/SmartFeatures';
import { GovDashboard } from './components/GovDashboard';

function App() {
  const [stage, setStage] = useState<FiltrationStage>(FiltrationStage.LANDING);
  const [applicantProfile, setApplicantProfile] = useState<ApplicantProfile | null>(null);
  const [leadershipStyle, setLeadershipStyle] = useState<string>('');
  const [analyticalScore, setAnalyticalScore] = useState<number>(0);
  const [finalResult, setFinalResult] = useState<FinalResult | null>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [levels, setLevels] = useState<LevelData[]>(LEVELS_CONFIG);
  const [activeLevelId, setActiveLevelId] = useState<number | null>(null);

  const handleStartFiltration = () => setStage(FiltrationStage.WELCOME);
  const handleStartPathFinder = () => setStage(FiltrationStage.PATH_FINDER);
  const handleSmartFeatures = () => setStage(FiltrationStage.SMART_FEATURES);
  const handleGovDashboard = () => setStage(FiltrationStage.GOV_DASHBOARD);

  const handleWelcomeNext = (data: ApplicantProfile) => {
    setApplicantProfile(data);
    setStage(FiltrationStage.PERSONALITY_TEST);
  };

  const handlePersonalityComplete = (style: string) => {
    setLeadershipStyle(style);
    setStage(FiltrationStage.ANALYTICAL_TEST);
  };

  const handleAnalyticalComplete = (score: number) => {
    setAnalyticalScore(score);
    setStage(FiltrationStage.PROJECT_EVALUATION);
  };

  const handleProjectEvaluationComplete = (projectEval: ProjectEvaluationResult) => {
    if (!applicantProfile) return;

    // Calculate final metrics based on all assessments
    const techBase = applicantProfile.techLevel === 'High' ? 90 : applicantProfile.techLevel === 'Medium' ? 70 : 40;
    const readinessBase = applicantProfile.projectStage === 'Product' ? 95 : applicantProfile.projectStage === 'Prototype' ? 75 : 50;

    // Personality and Ethics are simulated/based on consistency for this flow
    const personalityScore = 85; 
    const ethicsScore = 90; 

    // Combine analytical score with AI project evaluation scores
    const strategyScore = (analyticalScore + (projectEval.clarity * 5)) / 2;
    const finalReadiness = (readinessBase + (projectEval.readiness * 5)) / 2;

    const metrics = {
      readiness: finalReadiness,
      analysis: (analyticalScore + projectEval.market * 5) / 2,
      tech: techBase,
      personality: personalityScore,
      strategy: strategyScore,
      ethics: ethicsScore
    };

    const totalWeightedScore = Math.round(
      (metrics.readiness * 0.25) + 
      (metrics.analysis * 0.2) + 
      (metrics.tech * 0.15) + 
      (metrics.personality * 0.1) + 
      (metrics.strategy * 0.2) + 
      (metrics.ethics * 0.1)
    );

    // Qualification check
    const isQualified = totalWeightedScore >= 70 && projectEval.classification !== 'Red';

    const badges: Badge[] = [];
    if (leadershipStyle.includes('Balanced')) badges.push({ id: '1', name: 'وسام القيادة المتوازنة', icon: '⚖️', color: 'blue' });
    if (projectEval.classification === 'Green') badges.push({ id: '4', name: 'مشروع متميز', icon: '🚀', color: 'yellow' });
    if (analyticalScore > 80) badges.push({ id: '5', name: 'العقلية التحليلية', icon: '🧠', color: 'purple' });

    setFinalResult({
      score: totalWeightedScore,
      leadershipStyle,
      metrics,
      projectEval,
      isQualified,
      badges,
      recommendation: isQualified 
        ? "أنت تمتلك الجاهزية الكافية للانضمام لمسرعة الأعمال. فكرتك واعدة وتتطلب دعماً في التنفيذ." 
        : "نشكرك على مجهودك. نقترح التركيز على تطوير الجوانب التقنية ونموذج العمل قبل التقديم مرة أخرى."
    });

    setStage(FiltrationStage.ASSESSMENT_RESULT);
  };

  const handleResultContinue = () => {
    if (finalResult?.isQualified) setStage(FiltrationStage.FINAL_REPORT);
    else setStage(FiltrationStage.DEVELOPMENT_PLAN);
  };

  const handleStartIncubatorJourney = () => {
    if (!applicantProfile) return;
    setUserProfile({
      name: applicantProfile.codeName,
      startupName: 'مشروعي الناشئ',
      startupDescription: applicantProfile.goal,
      industry: applicantProfile.sector
    });
    setStage(FiltrationStage.DASHBOARD);
  };

  const handleLevelSelect = (id: number) => {
    setActiveLevelId(id);
    setStage(FiltrationStage.LEVEL_VIEW);
  };

  const handleLevelComplete = (id: number) => {
    setLevels(prev => prev.map(l => l.id === id ? { ...l, isCompleted: true } : l.id === id + 1 ? { ...l, isLocked: false } : l));
    setStage(FiltrationStage.DASHBOARD);
  };

  const handleOpenProjectBuilder = () => {
    setStage(FiltrationStage.PROJECT_BUILDER);
  };

  return (
    <div className="font-sans antialiased text-slate-900">
      {stage === FiltrationStage.LANDING && (
        <LandingPage 
          onStart={handleStartFiltration} 
          onPathFinder={handleStartPathFinder} 
          onSmartFeatures={handleSmartFeatures}
          onGovDashboard={handleGovDashboard}
        />
      )}
      {stage === FiltrationStage.SMART_FEATURES && <SmartFeatures onBack={() => setStage(FiltrationStage.LANDING)} />}
      {stage === FiltrationStage.GOV_DASHBOARD && <GovDashboard onBack={() => setStage(FiltrationStage.LANDING)} />}
      {stage === FiltrationStage.PATH_FINDER && <PathFinder onApproved={handleStartFiltration} onBack={() => setStage(FiltrationStage.LANDING)} />}
      {stage === FiltrationStage.WELCOME && <WelcomeStep onNext={handleWelcomeNext} onAdminLogin={() => alert('بوابة الإدارة قيد التطوير')} />}
      {stage === FiltrationStage.PERSONALITY_TEST && <PersonalityTest onComplete={handlePersonalityComplete} />}
      {stage === FiltrationStage.ANALYTICAL_TEST && applicantProfile && <AnalyticalTest profile={applicantProfile} onComplete={handleAnalyticalComplete} />}

      {/* New Project Evaluation Stage */}
      {stage === FiltrationStage.PROJECT_EVALUATION && applicantProfile && (
        <ProjectEvaluation 
          profile={applicantProfile} 
          onComplete={handleProjectEvaluationComplete} 
        />
      )}

      {stage === FiltrationStage.ASSESSMENT_RESULT && finalResult && <AssessmentResult result={finalResult} onContinue={handleResultContinue} />}
      {stage === FiltrationStage.FINAL_REPORT && applicantProfile && finalResult && <FinalReport profile={applicantProfile} result={finalResult} onStartJourney={handleStartIncubatorJourney} />}
      {stage === FiltrationStage.DEVELOPMENT_PLAN && applicantProfile && finalResult && <DevelopmentPlan profile={applicantProfile} result={finalResult} onRestart={() => setStage(FiltrationStage.WELCOME)} />}

      {stage === FiltrationStage.DASHBOARD && userProfile && (
        <>
          <div className="fixed top-24 left-4 z-50">
             <button 
              onClick={handleOpenProjectBuilder}
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-black shadow-xl shadow-blue-200 transition-all transform hover:scale-105 flex items-center gap-2"
             >
               <span>🚀</span>
               بناء مشروع ذكي
             </button>
          </div>
          <Dashboard user={userProfile} levels={levels} onSelectLevel={handleLevelSelect} onShowCertificate={() => setStage(FiltrationStage.CERTIFICATE)} onLogout={() => setStage(FiltrationStage.LANDING)} />
        </>
      )}

      {stage === FiltrationStage.PROJECT_BUILDER && (
        <ProjectBuilderMain 
          onBack={() => setStage(FiltrationStage.DASHBOARD)}
          onComplete={() => setStage(FiltrationStage.DASHBOARD)}
        />
      )}

      {stage === FiltrationStage.LEVEL_VIEW && userProfile && activeLevelId && <LevelView level={levels.find(l => l.id === activeLevelId)!} user={userProfile} onComplete={() => handleLevelComplete(activeLevelId)} onBack={() => setStage(FiltrationStage.DASHBOARD)} />}
      {stage === FiltrationStage.CERTIFICATE && userProfile && <Certificate user={userProfile} onClose={() => setStage(FiltrationStage.DASHBOARD)} />}
    </div>
  );
}

export default App;

