import { GoogleGenAI, Type } from "@google/genai";
import { ApplicantProfile, UserProfile, ProjectEvaluationResult, Question, AnalyticalQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = "gemini-3-flash-preview";

export const evaluateProjectIdea = async (description: string, profile: ApplicantProfile): Promise<ProjectEvaluationResult> => {
  const prompt = `
    أنت مستشار ريادي خبير في مسرعة أعمال. قم بتقييم فكرة المشروع التالية:
    قطاع: ${profile.sector} | مرحلة: ${profile.projectStage}
    الفكرة: "${description}"

    حلل عبر 5 محاور (درجة من 20 لكل محور):
    1. Clarity: وضوح المشكلة والحل.
    2. Value: القيمة الحقيقية.
    3. Innovation: الابتكار.
    4. Market: الجدوى السوقية.
    5. Readiness: الجاهزية.

    رد JSON فقط بالهيكل المحدد:
    {
      "clarity": number,
      "value": number,
      "innovation": number,
      "market": number,
      "readiness": number,
      "totalScore": number,
      "aiOpinion": "نص باللغة العربية",
      "classification": "Green" | "Yellow" | "Red"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            clarity: { type: Type.NUMBER },
            value: { type: Type.NUMBER },
            innovation: { type: Type.NUMBER },
            market: { type: Type.NUMBER },
            readiness: { type: Type.NUMBER },
            totalScore: { type: Type.NUMBER },
            aiOpinion: { type: Type.STRING },
            classification: { type: Type.STRING, enum: ['Green', 'Yellow', 'Red'] }
          },
          required: ["clarity", "value", "innovation", "market", "readiness", "totalScore", "aiOpinion", "classification"]
        }
      }
    });
    return JSON.parse(response.text || "{}");
  } catch (e) {
    return {
      clarity: 10, value: 10, innovation: 10, market: 10, readiness: 10,
      totalScore: 50, aiOpinion: "عذراً، حدث خطأ في التحليل.",
      classification: 'Yellow'
    };
  }
};

