          recoveryPlan: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["brutalTruth", "probability", "financialLoss", "operationalImpact", "missingQuestions", "recoveryPlan"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

// Added to fix GovDashboard.tsx error
export const getGovInsights = async (): Promise<GovStats> => {
  const prompt = `أنتج إحصائيات ورؤى حكومية حول حالة التصدير والقطاعات الجاهزة. الرد JSON فقط.`;
  const response = await ai.models.generateContent({
    model: MODEL_NAME,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          riskyMarkets: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                failRate: { type: Type.NUMBER }
              },
              required: ["name", "failRate"]
            }
          },
          readySectors: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                score: { type: Type.NUMBER }
              },
              required: ["name", "score"]
            }
          },
          commonFailReasons: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                reason: { type: Type.STRING },
                percentage: { type: Type.NUMBER }
              },
              required: ["reason", "percentage"]
            }
          },
          regulatoryGaps: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["riskyMarkets", "readySectors", "commonFailReasons", "regulatoryGaps"]
      }
    }
  });
  return JSON.parse(response.text || "{}");
};

