                  {level.description}
                </p>

                <div className="mt-auto">
                  {!level.isLocked && !level.isCompleted && (
                    <div 
                      className="w-full py-3.5 bg-blue-50 group-hover:bg-blue-600 group-hover:text-white text-blue-600 rounded-xl text-sm font-bold transition-all flex items-center justify-center gap-2 group-hover:shadow-lg"
                    >
                      ابدأ التدريب
                      <svg className="w-4 h-4 transform group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                      </svg>
                    </div>
                  )}
                  {level.isCompleted && (
                    <div className="w-full py-3.5 bg-green-50 text-green-700 rounded-xl text-sm font-bold transition-colors border border-green-100 flex items-center justify-center gap-2">
                      <span>مكتمل</span>
                    </div>
                  )}
                  {level.isLocked && (
                    <div className="w-full py-3.5 bg-gray-100 text-gray-400 rounded-xl text-sm font-bold flex items-center justify-center gap-2">
                      مغلق حالياً
                    </div>
                  )}
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-16 text-center text-gray-500 bg-white rounded-3xl border border-gray-100 border-dashed animate-fade-in-up">
               <div className="w-16 h-16 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-4">
                  <svg className="w-8 h-8 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                     <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
               </div>
               <p className="text-lg font-bold text-gray-800">لا توجد مستويات تطابق بحثك</p>
               <p className="text-sm">حاول البحث بكلمة أخرى مثل "سوق" أو "منتج".</p>
               <button 
                onClick={(e) => { e.stopPropagation(); setSearchTerm(''); }}
                className="mt-4 text-blue-600 font-bold hover:underline"
               >
                 عرض جميع المستويات
               </button>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

